@inject sv_28eced75fb2f46598e14f14241232234.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mt-3" style="max-width: 500px;">
    <div class="card-body">
        <h5 class="card-title">@WarehouseState.CurrentWarehouseName</h5>
        <p class="card-text">
            Low-stock alerts:
            <span class="badge @BadgeClass fs-6">@AlertService.CurrentLowStockCount items</span>
        </p>
        <p class="text-muted small">Refreshes every 10 seconds. Last update: @_lastUpdate.ToString("HH:mm:ss")</p>
    </div>
</div>

@code {
    private DateTime _lastUpdate = DateTime.Now;

    private string BadgeClass => AlertService.CurrentLowStockCount > 5 ? "bg-danger" : "bg-warning text-dark";

    protected override void OnInitialized()
    {
        AlertService.Subscribe();
        AlertService.OnAlertDataChanged += OnDataChanged;
        WarehouseState.OnChange += OnWarehouseChanged;
    }

    private void OnDataChanged()
    {
        _lastUpdate = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    private void OnWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= OnDataChanged;
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.Unsubscribe();
    }
}

